export interface ServiceProperties {
  /**
   * Date and time the service is to be provided, in [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601#Combined_date_and_time_representations) format.
   * For example, the start time of a class.
   */
  scheduledDate?: Date | null;
  /**
   * The number of people participating in the service. For example, the number of people attending a class or the number of people per hotel room.
   * @min 1
   * @max 10000
   */
  numberOfParticipants?: number | null;
  /**
   * Date and time the service is to be ended, in [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601#Combined_date_and_time_representations) format.
   * For example, the date and time a class will end.
   * @internal
   */
  endDate?: Date | null;
}

export interface ChargeOrderResponse {
  /**
   * Payments created.
   * @maxSize 100
   */
  payments?: Payment[];
  /** Updated order transaction history reflecting all payments statuses */
  orderTransactions?: OrderTransactions;
  /**
   * (Optional) Charge response token (for regular charge) from payment gateway. Present when non-delayed charge is requested.
   * @minLength 1
   * @maxLength 300
   */
  regularChargeResponseToken?: string | null;
}

export interface Payment
  extends PaymentPaymentDetailsOneOf,
    PaymentReceiptInfoOneOf,
    PaymentStatusDetailsOneOf {
  /** Regular payment details. */
  regularPaymentDetails?: RegularPaymentDetails;
  /** Gift card payment details. */
  giftcardPaymentDetails?: GiftCardPaymentDetails;
  /** Membership payment details. */
  membershipPaymentDetails?: MembershipPaymentDetails;
  /**
   * Receipt created by Wix
   * @internal
   */
  wixReceipt?: WixReceiptInfo;
  /**
   * Receipt created by an external system.
   * @internal
   */
  externalReceipt?: ExternalReceiptInfo;
  /** @internal */
  canceled?: CanceledStatusDetails;
  /** @internal */
  declined?: DeclinedStatusDetails;
  /** @internal */
  voided?: VoidedStatusDetails;
  /**
   * Payment ID.
   * @format GUID
   * @readonly
   */
  _id?: string | null;
  /** Date and time the payment was created in [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601#Combined_date_and_time_representations) format. Defaults to current time when not provided. */
  _createdDate?: Date | null;
  /**
   * Date and time the payment was last updated in [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601#Combined_date_and_time_representations) format.
   * @readonly
   */
  _updatedDate?: Date | null;
  /** Payment amount. */
  amount?: Price;
  /**
   * Whether refunds for this payment are disabled.
   * + `true`: This payment is not refundable.
   * + `false`: This payment may be refunded. However, this ultimately depends on the payment provider.
   */
  refundDisabled?: boolean;
  /**
   * Whether receipt generation is allowed for this payment.
   * + `true`: This payment supports receipt generation.
   * + `false`: This payment doesn't support receipt generation, or a receipt was already generated.
   * @readonly
   */
  supportReceiptGeneration?: boolean;
  /** Details about cash rounding applied to this payment, when relevant. */
  cashRounding?: CashRoundingDetails;
  /**
   * Overall payment status.
   *
   * Gift card and membership payments support only `APPROVED`, `PENDING`, `CANCELED`, `DECLINED`, and `VOIDED`. The remaining values apply to regular payments.
   */
  status?: PaymentStatusWithLiterals;
  /**
   * Detailed payment status information including gateway reason codes and status-specific details.
   * @internal
   */
  paymentStatusDetails?: PaymentStatusDetails;
  /**
   * Location where the payment was processed.
   * @internal
   * @format GUID
   * @immutable
   */
  locationId?: string | null;
  /**
   * ID linking this payment to the charge request that created it. Matches the `idempotencyKey` sent in the Charge Order request.
   * @format GUID
   */
  chargeCorrelationId?: string | null;
}

