export enum TransactionStatus {
  UNDEFINED = 'UNDEFINED',
  APPROVED = 'APPROVED',
  PENDING = 'PENDING',
  PENDING_MERCHANT = 'PENDING_MERCHANT',
  CANCELED = 'CANCELED',
  DECLINED = 'DECLINED',
  REFUNDED = 'REFUNDED',
  PARTIALLY_REFUNDED = 'PARTIALLY_REFUNDED',
  AUTHORIZED = 'AUTHORIZED',
  VOIDED = 'VOIDED',
}

/** @enumType */
export type TransactionStatusWithLiterals =
  | TransactionStatus
  | 'UNDEFINED'
  | 'APPROVED'
  | 'PENDING'
  | 'PENDING_MERCHANT'
  | 'CANCELED'
  | 'DECLINED'
  | 'REFUNDED'
  | 'PARTIALLY_REFUNDED'
  | 'AUTHORIZED'
  | 'VOIDED';

export interface CreditCardPaymentMethodDetails {
  /**
   * The last 4 digits of the card number.
   * @maxLength 4
   */
  lastFourDigits?: string | null;
  /**
   * Card issuer's brand.
   * @maxLength 100
   */
  brand?: string | null;
}

export interface AuthorizationDetails {
  /**
   * Whether the authorized payment is of a delayed capture.
   * @readonly
   */
  delayedCapture?: boolean;
  /** Date and time the payment was authorized in [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601#Combined_date_and_time_representations) format. */
  authorizedDate?: Date | null;
  /**
   * List of captures associated with payment
   * In case of failed it can be replaced with new one with PENDING or SUCCESS statuses
   * @maxSize 1
   */
  captures?: AuthorizationCapture[];
  /** Void associated with payment */
  void?: AuthorizationVoid;
  /** Scheduled action for this transaction */
  scheduledAction?: V1ScheduledAction;
}

export interface AuthorizationCapture {
  /**
   * Capture ID.
   * @format GUID
   * @readonly
   */
  _id?: string | null;
  /** Status of this capture action */
  status?: AuthorizationCaptureStatusWithLiterals;
  /**
   * Amount of this capture
   * @immutable
   */
  amount?: Price;
  /** Date and time the capture was initiated in [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601#Combined_date_and_time_representations) format. */
  _createdDate?: Date | null;
  /** In case of status is FAILED may contain failure details */
  failureDetails?: AuthorizationActionFailureDetails;
}

export enum AuthorizationCaptureStatus {
  /** Capture operation still in progress. */
  PENDING = 'PENDING',
  /** Capture operation succeeded. */
  SUCCEEDED = 'SUCCEEDED',
  /** Capture operation failed. */
  FAILED = 'FAILED',
}

/** @enumType */
export type AuthorizationCaptureStatusWithLiterals =
  | AuthorizationCaptureStatus
  | 'PENDING'
  | 'SUCCEEDED'
  | 'FAILED';

export interface AuthorizationActionFailureDetails {
  /** @maxLength 100 */
  failureCode?: string;
}

export interface AuthorizationVoid {
  /** Status of this void action */
  status?: AuthorizationVoidStatusWithLiterals;
  /** Date and time the void was initiated in [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601#Combined_date_and_time_representations) format. */
  voidedDate?: Date | null;
  /** In case of status is FAILED may contain failure details */
  failureDetails?: AuthorizationActionFailureDetails;
  /** Reason of void action */
  reason?: ReasonWithLiterals;
}

export enum AuthorizationVoidStatus {
  /** Void operation still in progress. */
  PENDING = 'PENDING',
  /** Void operation succeeded. */
  SUCCEEDED = 'SUCCEEDED',
  /** Void operation failed. */
  FAILED = 'FAILED',
}

/** @enumType */
export type AuthorizationVoidStatusWithLiterals =
  | AuthorizationVoidStatus
  | 'PENDING'
  | 'SUCCEEDED'
  | 'FAILED';

/** Reason the authorization was voided. */
export enum Reason {
  /** Authorization was voided by user. */
  MANUAL = 'MANUAL',
  /** Authorization passed execution date. */
  SCHEDULED = 'SCHEDULED',
}

/** @enumType */
export type ReasonWithLiterals = Reason | 'MANUAL' | 'SCHEDULED';

export interface V1ScheduledAction {
  /** Type of the action. */
  actionType?: ActionTypeWithLiterals;
  /** The date and time of the action. */
  executionDate?: Date | null;
}

export enum ActionType {
  VOID = 'VOID',
  CAPTURE = 'CAPTURE',
}

/** @enumType */
export type ActionTypeWithLiterals = ActionType | 'VOID' | 'CAPTURE';

export interface Chargeback {
  /**
   * Chargeback ID.
   * @format GUID
   * @readonly
   * @immutable
   */
  _id?: string;
  /**
   * Date and time the chargeback was created in [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601#Combined_date_and_time_representations) format. Defaults to current time when not provided.
   * @readonly
   * @immutable
   */
  _createdDate?: Date | null;
  /**
   * Date and time the chargeback was updated in [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601#Combined_date_and_time_representations) format. Defaults to current time when not provided.
   * @readonly
   */
  _updatedDate?: Date | null;
  /**
   * Amount.
   * @readonly
   * @immutable
   */
  amount?: Price;
  /**
   * Reversal amount. Present only when status is REVERSED.
   * @readonly
   */
  reversalAmount?: Price;
  /**
   * Status.
   *
   * Default: `"APPROVED"`.
   */
  status?: ChargebackStatusWithLiterals;
  /**
   * External chargeback ID.
   * @format GUID
   * @readonly
   * @immutable
   */
  externalId?: string | null;
}

export enum ChargebackStatus {
  /** Chargeback was approved. */
  APPROVED = 'APPROVED',
  /** Chargeback was reversed. */
  REVERSED = 'REVERSED',
}

/** @enumType */
export type ChargebackStatusWithLiterals =
  | ChargebackStatus
  | 'APPROVED'
  | 'REVERSED';

